package com.opensocket.aievent.core.resourceaccess.contract;
import com.opensocket.aievent.core.iam.security.contract.AuthenticationContext;import com.opensocket.aievent.core.iam.security.contract.PrincipalRef;import com.opensocket.aievent.core.iam.security.contract.TenantRef;import java.util.Map;
/** Administrative simulation request. Actor authentication is distinct from the simulated target principal. */
public record AuthorizationSimulationRequest(AuthenticationContext actorAuthentication,PrincipalRef targetPrincipal,TenantRef activeTenant,ResourceAction action,ResourceRef resourceRef,VisibilityLevel requestedVisibility,String purpose,String correlationId,SecurityEpoch presentedEpoch,Map<String,String> trustedFlowContext){
 public AuthorizationSimulationRequest{if(actorAuthentication==null)throw new IllegalArgumentException("actorAuthentication is required");if(targetPrincipal==null)throw new IllegalArgumentException("targetPrincipal is required");if(activeTenant==null)throw new IllegalArgumentException("activeTenant is required");if(!actorAuthentication.activeTenant().equals(activeTenant))throw new IllegalArgumentException("actor tenant and active tenant must match");if(action==null)throw new IllegalArgumentException("action is required");if(resourceRef==null)throw new IllegalArgumentException("resourceRef is required");if(!activeTenant.tenantId().equals(resourceRef.tenantId()))throw new IllegalArgumentException("active tenant and resource tenant must match");requestedVisibility=requestedVisibility==null?VisibilityLevel.NONE:requestedVisibility;purpose=req(purpose,"purpose");correlationId=req(correlationId,"correlationId");presentedEpoch=presentedEpoch==null?SecurityEpoch.ZERO:presentedEpoch;trustedFlowContext=trustedFlowContext==null?Map.of():Map.copyOf(trustedFlowContext);}
 private static String req(String v,String f){if(v==null||v.isBlank())throw new IllegalArgumentException(f+" is required");return v.trim();}
}
